from itertools import combinations
G=[[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0],[0]*7,[0]*7,[0]*7]
cells={(r,c) for r,row in enumerate(G) for c,v in enumerate(row) if v==8}
tiles=[]
# squares
for r in range(6):
 for c in range(6):
  s={(r+i,c+j) for i in range(2) for j in range(2)}
  if s<=cells: tiles.append((s,1,'sq',(r,c)))
# L triominoes in 2x2 with one missing corner; known labels
misslab={(0,0):2,(1,0):3,(0,1):4,(1,1):None}
for r in range(6):
 for c in range(6):
  full={(r+i,c+j) for i in range(2) for j in range(2)}
  for m,lab in misslab.items():
   s=full-{(r+m[0],c+m[1])}
   if s<=cells: tiles.append((s,lab,'L', (r,c,m)))
solutions=[]
def search(rem,chosen):
 if not rem:
  if sum(t[2]=='sq' for t in chosen)==1 and sum(t[2]=='L' for t in chosen)==4: solutions.append(chosen.copy())
  return
 if len(chosen)>5:return
 cell=min(rem)
 for t in tiles:
  s=t[0]
  if cell in s and s<=rem:
   search(rem-s,chosen+[t])
search(cells,[])
len(cells),len(tiles),len(solutions), [[(t[1],t[2],t[3]) for t in sol] for sol in solutions[:10]]

